/**
 * @summary Upload Ingestion Item
 */
export const uploadIngestionItem = (
    bodyUploadIngestionItem: BodyUploadIngestionItem,
 signal?: AbortSignal
) => {

      const formData = new FormData();
formData.append(`file`, bodyUploadIngestionItem.file);
if(bodyUploadIngestionItem.project_id !== undefined && bodyUploadIngestionItem.project_id !== null) {
 formData.append(`project_id`, bodyUploadIngestionItem.project_id);
 }

      return apiMutator<IngestionUploadResponse>(
      {url: `/api/v1/ingestion/items`, method: 'POST',
      headers: {'Content-Type': 'multipart/form-data', },
       data: formData, signal
    },
      );
    }




export const getUploadIngestionItemMutationOptions = <TError = HTTPValidationError,
    TContext = unknown>(options?: { mutation?:UseMutationOptions<Awaited<ReturnType<typeof uploadIngestionItem>>, TError,{data: BodyUploadIngestionItem}, TContext>, }
): UseMutationOptions<Awaited<ReturnType<typeof uploadIngestionItem>>, TError,{data: BodyUploadIngestionItem}, TContext> => {

const mutationKey = ['uploadIngestionItem'];
const {mutation: mutationOptions} = options ?
      options.mutation && 'mutationKey' in options.mutation && options.mutation.mutationKey ?
      options
      : {...options, mutation: {...options.mutation, mutationKey}}
      : {mutation: { mutationKey, }};




      const mutationFn: MutationFunction<Awaited<ReturnType<typeof uploadIngestionItem>>, {data: BodyUploadIngestionItem}> = (props) => {
          const {data} = props ?? {};

          return  uploadIngestionItem(data,)
        }






  return  { mutationFn, ...mutationOptions }}

    export type UploadIngestionItemMutationResult = NonNullable<Awaited<ReturnType<typeof uploadIngestionItem>>>
    export type UploadIngestionItemMutationBody = BodyUploadIngestionItem
